jsonTools.init:
function init(bundle) {
  if (window._eliAdminTelemetryInspectorBooted) return;
  window._eliAdminTelemetryInspectorBooted = true;
  if (!eli || !eli.storage || !eli.ui || !eli.register) return;

  var STORE_CONFIG = "config";
  var ROW_PREFIX = "_telemetry_";

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _fmtTool(t) { return String(t).replace(/_/g, " "); }
  function _fmtTime(ms) {
    if (!ms) return "—";
    try { return new Date(ms).toLocaleString(); } catch (e) { return String(ms); }
  }
  function _fmtCost(usd) {
    var n = Number(usd || 0);
    if (!n) return "$0";
    if (n < 0.01) return "$" + n.toFixed(4);
    return "$" + n.toFixed(2);
  }
  // Inline price table — matches eli_telemetry/engine.js etPriceTable.
  // Replicated so the inspector doesn't need a cross-tool dependency.
  function _estCost(tokensMap) {
    var prices = {
      "gemini-3.1-flash-lite-preview": { in: 0.04, out: 0.20 },
      "gemini-3.1-flash":              { in: 0.075, out: 0.30 },
      "gemini-2.5-flash":              { in: 0.075, out: 0.30 },
      "gemini-2.5-flash-lite-preview": { in: 0.04, out: 0.20 },
      "gemini-2.5-pro":                { in: 1.25, out: 5.00 },
      "gemini-1.5-pro":                { in: 1.25, out: 5.00 },
      "gemini-1.5-flash":              { in: 0.075, out: 0.30 },
      "_default":                      { in: 0.075, out: 0.30 },
    };
    if (!tokensMap || typeof tokensMap !== "object") return 0;
    var total = 0;
    Object.keys(tokensMap).forEach(function (model) {
      var t = tokensMap[model] || {};
      var price = prices[model] || prices._default;
      var inTok = Number(t.promptTokens) || 0;
      var outTok = Number(t.candidatesTokens) || 0;
      total += (inTok * price.in + outTok * price.out) / 1000000;
    });
    return total;
  }

  function _readLocalRows() {
    return eli.storage.getAll(STORE_CONFIG).then(function (rows) {
      return (rows || []).filter(function (r) {
        return r && typeof r.key === "string" && r.key.indexOf(ROW_PREFIX) === 0;
      }).sort(function (a, b) {
        return String(b.date || "").localeCompare(String(a.date || ""));
      });
    }).catch(function () { return []; });
  }

  function _renderEmpty(mount) {
    mount.innerHTML =
      '<div style="padding:40px 24px;text-align:center;font-family:Inter,system-ui,sans-serif;">' +
        '<div style="font-size:32px;margin-bottom:12px;">📭</div>' +
        '<div style="font-size:14px;font-weight:700;color:#0f172a;margin-bottom:6px;">No local telemetry rows yet</div>' +
        '<div style="font-size:12px;color:#64748b;line-height:1.5;max-width:380px;margin:0 auto;">' +
          'Launch any tool (Review Redlines, Compare, Error Review, etc.) and a row will be created in IDB for today\'s date. Then re-open this inspector to see the running counts.' +
        '</div>' +
      '</div>';
  }

  function _render(mount, rows) {
    if (!rows || !rows.length) { _renderEmpty(mount); return; }
    var userKey = rows[0].userKey || "?";
    var userName = rows[0].userName || "?";
    // Doc-wide totals across all days for the inspector header.
    var totalToolsUsed = {};
    var totalCost = 0;
    var totalCalls = 0;
    rows.forEach(function (r) {
      var tu = r.toolsUsed || {};
      Object.keys(tu).forEach(function (k) {
        totalToolsUsed[k] = (totalToolsUsed[k] || 0) + (Number(tu[k]) || 0);
      });
      totalCost += _estCost(r.tokens || {});
      Object.values(r.tokens || {}).forEach(function (m) {
        totalCalls += Number((m && m.calls) || 0);
      });
    });
    var totalLaunchesAllDays = Object.keys(totalToolsUsed).reduce(function (n, k) {
      return n + totalToolsUsed[k];
    }, 0);
    var html = '';
    html += '<div style="font-family:Inter,system-ui,sans-serif;padding:20px 24px;background:#f8fafc;min-height:100vh;">';
    // Header
    html +=   '<div style="background:linear-gradient(135deg,#0f172a,#1e293b);color:#fff;padding:18px 22px;margin-bottom:18px;">';
    html +=     '<div style="font-size:10px;font-weight:800;opacity:0.78;text-transform:uppercase;letter-spacing:1.4px;">ADMIN — Local IDB Inspector</div>';
    html +=     '<div style="font-size:20px;font-weight:800;margin-top:4px;">📊 Telemetry Preview — ' + _esc(userName) + ' (' + _esc(userKey) + ')</div>';
    html +=     '<div style="font-size:11.5px;opacity:0.82;margin-top:6px;font-weight:600;">';
    html +=       rows.length + ' day' + (rows.length === 1 ? '' : 's') + ' in IDB · ';
    html +=       totalLaunchesAllDays + ' total launches · ';
    html +=       totalCalls + ' AI calls · ';
    html +=       _fmtCost(totalCost) + ' total AI spend';
    html +=     '</div>';
    html +=     '<div style="font-size:10.5px;opacity:0.7;margin-top:4px;font-style:italic;">This is the LIVE local IDB state. These counts go to CDN on the next push.</div>';
    html +=   '</div>';
    // Per-day breakdown
    rows.forEach(function (r) {
      var toolEntries = Object.keys(r.toolsUsed || {}).map(function (t) {
        return { tool: t, count: Number(r.toolsUsed[t]) || 0 };
      }).sort(function (a, b) { return b.count - a.count; });
      var dayLaunches = toolEntries.reduce(function (n, e) { return n + e.count; }, 0);
      var dayCost = _estCost(r.tokens || {});
      var dayCalls = Object.values(r.tokens || {}).reduce(function (n, m) {
        return n + Number((m && m.calls) || 0);
      }, 0);
      html += '<div style="background:#fff;border:1px solid #e2e8f0;margin-bottom:14px;box-shadow:0 1px 2px rgba(15,23,42,0.04);">';
      // Day header — navy with date + totals + activity window.
      html +=   '<div style="background:linear-gradient(135deg,#1e3a8a,#1565c0);color:#fff;padding:10px 14px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">';
      html +=     '<div style="font-weight:800;font-size:14px;">' + _esc(r.date) + '</div>';
      html +=     '<div style="font-size:11px;opacity:0.92;display:flex;gap:14px;flex-wrap:wrap;">';
      html +=       '<span><strong>' + dayLaunches + '</strong> launch' + (dayLaunches === 1 ? '' : 'es') + '</span>';
      if (dayCalls > 0) html += '<span><strong>' + dayCalls + '</strong> AI call' + (dayCalls === 1 ? '' : 's') + '</span>';
      if (dayCost > 0) html += '<span style="color:#5eead4;font-weight:700;">' + _fmtCost(dayCost) + '</span>';
      html +=     '</div>';
      html +=   '</div>';
      // Activity window
      if (r.firstActiveAt || r.lastActiveAt) {
        html += '<div style="padding:6px 14px;background:#f1f5f9;border-bottom:1px solid #e2e8f0;font-size:10.5px;color:#475569;">';
        html +=   'Active window: ' + _fmtTime(r.firstActiveAt) + ' → ' + _fmtTime(r.lastActiveAt);
        html += '</div>';
      }
      // Per-tool table
      html += '<div style="padding:12px 14px;">';
      if (toolEntries.length === 0) {
        html += '<div style="font-size:11.5px;color:#94a3b8;font-style:italic;">No tool launches for this day yet (AI tokens may have been recorded).</div>';
      } else {
        html += '<div style="font-size:9.5px;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:6px;">Per Tool</div>';
        html += '<table style="width:100%;border-collapse:collapse;font-size:12px;">';
        html += '<thead><tr style="background:#f8fafc;text-align:left;border-bottom:1px solid #e2e8f0;">';
        html +=   '<th style="padding:6px 10px;font-weight:700;color:#334155;">Tool</th>';
        html +=   '<th style="padding:6px 10px;font-weight:700;color:#334155;text-align:right;">Launches</th>';
        html += '</tr></thead><tbody>';
        toolEntries.forEach(function (e, i) {
          var zebra = i % 2 === 0 ? "#fff" : "#fafbfc";
          html += '<tr style="background:' + zebra + ';border-bottom:1px solid #f1f5f9;">';
          html +=   '<td style="padding:6px 10px;color:#334155;">' + _esc(_fmtTool(e.tool)) + '</td>';
          html +=   '<td style="padding:6px 10px;text-align:right;color:#0f172a;font-weight:700;">' + e.count + '</td>';
          html += '</tr>';
        });
        html += '</tbody></table>';
      }
      // Token breakdown
      var tokensMap = r.tokens || {};
      var tokenModels = Object.keys(tokensMap);
      if (tokenModels.length > 0) {
        html += '<div style="font-size:9.5px;font-weight:800;color:#0d9488;text-transform:uppercase;letter-spacing:0.1em;margin-top:14px;margin-bottom:6px;">AI Tokens (by model)</div>';
        html += '<table style="width:100%;border-collapse:collapse;font-size:12px;">';
        html += '<thead><tr style="background:#f0fdfa;text-align:left;border-bottom:1px solid #99f6e4;">';
        html +=   '<th style="padding:6px 10px;font-weight:700;color:#0f766e;">Model</th>';
        html +=   '<th style="padding:6px 10px;font-weight:700;color:#0f766e;text-align:right;">Calls</th>';
        html +=   '<th style="padding:6px 10px;font-weight:700;color:#0f766e;text-align:right;">Prompt</th>';
        html +=   '<th style="padding:6px 10px;font-weight:700;color:#0f766e;text-align:right;">Response</th>';
        html +=   '<th style="padding:6px 10px;font-weight:700;color:#0f766e;text-align:right;">Cost</th>';
        html += '</tr></thead><tbody>';
        tokenModels.forEach(function (model) {
          var m = tokensMap[model] || {};
          var modelCost = _estCost({ [model]: m });
          html += '<tr style="border-bottom:1px solid #f1f5f9;">';
          html +=   '<td style="padding:6px 10px;color:#334155;font-family:ui-monospace,monospace;font-size:11px;">' + _esc(model) + '</td>';
          html +=   '<td style="padding:6px 10px;text-align:right;color:#0f172a;font-weight:600;">' + (Number(m.calls) || 0) + '</td>';
          html +=   '<td style="padding:6px 10px;text-align:right;color:#475569;">' + (Number(m.promptTokens) || 0).toLocaleString() + '</td>';
          html +=   '<td style="padding:6px 10px;text-align:right;color:#475569;">' + (Number(m.candidatesTokens) || 0).toLocaleString() + '</td>';
          html +=   '<td style="padding:6px 10px;text-align:right;color:#0d9488;font-weight:700;">' + _fmtCost(modelCost) + '</td>';
          html += '</tr>';
        });
        html += '</tbody></table>';
      }
      html += '</div>'; // body padding
      html += '</div>'; // day card
    });
    // Footer / actions. Both reset buttons are LOCAL ONLY — they touch
    // IDB on this machine only. The CDN digest is untouched until the
    // next scheduled push (which would then propagate the cleared
    // counts via MAX merge). To wipe CDN-side data you'd have to edit
    // usage/<userKey>.json in eli-data directly.
    html += '<div style="margin-top:14px;display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap;">';
    html +=   '<button id="atiResetToday" style="padding:8px 14px;font-size:11px;font-weight:700;background:#fff;border:1px solid #fca5a5;color:#b91c1c;cursor:pointer;border-radius:0;" title="Zero out today\'s tool counts in LOCAL IDB only. CDN is untouched.">🧹 Reset Today (local)</button>';
    html +=   '<button id="atiResetAll" style="padding:8px 14px;font-size:11px;font-weight:700;background:#fff;border:1px solid #fca5a5;color:#b91c1c;cursor:pointer;border-radius:0;" title="Delete every _telemetry_* row in LOCAL IDB. CDN is untouched.">🗑 Reset All (local)</button>';
    html +=   '<button id="atiRefresh" style="padding:8px 14px;font-size:11px;font-weight:700;background:#fff;border:1px solid #cbd5e1;color:#475569;cursor:pointer;border-radius:0;">↻ Refresh</button>';
    html += '</div>';
    html += '<div style="margin-top:10px;font-size:10.5px;color:#64748b;font-style:italic;line-height:1.5;">';
    html +=   '<b>Both reset buttons are LOCAL ONLY.</b> They clear this machine\'s IDB. The CDN digest at <code>usage/' + _esc(userKey) + '.json</code> is not touched. ';
    html +=   'If counts look inflated: that\'s historical data from before the v34/v38 fixes. <b>Force-update eli_telemetry + legal_risks + usage_risks + RELOAD the taskpane</b>, then hit Reset Today to clear the bloat. New launches will count correctly going forward.';
    html += '</div>';
    html += '</div>';
    mount.innerHTML = html;
    var refreshBtn = mount.querySelector("#atiRefresh");
    if (refreshBtn) {
      refreshBtn.onclick = function () {
        mount.innerHTML = '<div style="padding:40px;text-align:center;color:#64748b;font-family:Inter,system-ui,sans-serif;">Reading IDB…</div>';
        _readLocalRows().then(function (r) { _render(mount, r); });
      };
    }
    // Script Lab iframe blocks native confirm() silently — must use
    // eli.ui.confirm. (Per CLAUDE.md "Forbidden patterns".)
    var resetTodayBtn = mount.querySelector("#atiResetToday");
    if (resetTodayBtn) {
      resetTodayBtn.onclick = function () {
        var today = new Date().toISOString().slice(0, 10);
        var todayRow = rows.find(function (r) { return r.date === today; });
        if (!todayRow) {
          if (typeof showToast === "function") showToast("No row for today (" + today + ") in IDB — nothing to reset.", "info");
          return;
        }
        var summary = Object.keys(todayRow.toolsUsed || {})
          .map(function (k) { return k + ":" + todayRow.toolsUsed[k]; })
          .join(", ") || "(no tool launches yet)";
        eli.ui.confirm({
          title: "Reset today's local telemetry?",
          message:
            "Zero out today's tool counts (" + today + ") in local IDB.\n\n" +
            "Current: " + summary + "\n\n" +
            "Local-only. CDN data is untouched. New launches after reload count from 0.",
          confirmLabel: "Reset Today",
          danger: true,
        }).then(function (ok) {
          if (!ok) return;
          todayRow.toolsUsed = {};
          todayRow.tokens = {};
          eli.storage.put(STORE_CONFIG, todayRow).then(function () {
            if (typeof showToast === "function") showToast("Today's local counts reset to 0", "ok");
            _readLocalRows().then(function (r) { _render(mount, r); });
          }).catch(function (e) {
            if (typeof showToast === "function") showToast("Reset failed: " + (e && e.message || "unknown"), "err");
          });
        });
      };
    }
    var resetAllBtn = mount.querySelector("#atiResetAll");
    if (resetAllBtn) {
      resetAllBtn.onclick = function () {
        eli.ui.confirm({
          title: "Delete ALL local telemetry rows?",
          message:
            "Removes every _telemetry_* row in local IDB (" + rows.length + " day row" +
            (rows.length === 1 ? "" : "s") + ").\n\n" +
            "Local-only. CDN data is untouched. All historical local counts " +
            "disappear; new launches start from 0.",
          confirmLabel: "Delete All Local",
          danger: true,
        }).then(function (ok) {
          if (!ok) return;
          Promise.all(rows.map(function (r) {
            return eli.storage.delete(STORE_CONFIG, r.key).catch(function () {});
          })).then(function () {
            if (typeof showToast === "function") showToast("All local telemetry rows deleted", "ok");
            _readLocalRows().then(function (r) { _render(mount, r); });
          });
        });
      };
    }
  }

  function _open() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAdminTelemetryInspector"); } catch (e) {}
    var out = eli.ui && typeof eli.ui.claimOutput === "function" ? eli.ui.claimOutput() : document.getElementById("output");
    if (!out) {
      if (typeof showToast === "function") showToast("Dashboard root missing", "err");
      return;
    }
    // Force block layout so the kernel's flex doesn't squish our content.
    var wrap = document.createElement("div");
    wrap.style.cssText = "display:block;width:100%;box-sizing:border-box;";
    out.appendChild(wrap);
    wrap.innerHTML = '<div style="padding:40px;text-align:center;color:#64748b;font-family:Inter,system-ui,sans-serif;">Reading IDB…</div>';
    _readLocalRows().then(function (rows) { _render(wrap, rows); });
  }

  eli.register({
    tile: { app_admin_telemetry_inspector: _open },
    admin_telemetry_inspector: { open: _open },
  });

  eli.log.event("tool", "admin_telemetry_inspector_initialized", {});
}
